import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, time, active)
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)
    time_counter = 0

    def is_valid(entry_id):
        o = book.get(entry_id)
        return o is not None and o['active'] and o['qty'] > 0

    def match_incoming(side, price, qty, order_id, is_market):
        # price: relevant price for limit/ioc; ignored if is_market True
        nonlocal trades
        remaining = qty
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_time, top_id = heap[0]
            else:
                neg_price, top_time, top_id = heap[0]
                top_price = -neg_price

            if not is_valid(top_id):
                heapq.heappop(heap)
                continue

            # price check
            if not is_market:
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            # valid match, pop it
            heapq.heappop(heap)
            resting = book[top_id]
            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([order_id, top_id, resting['price'], trade_qty])
            else:
                trades.append([top_id, order_id, resting['price'], trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] > 0:
                # push back with same key info
                if side == 'buy':
                    heapq.heappush(heap, (resting['price'], resting['time'], top_id))
                else:
                    heapq.heappush(heap, (-resting['price'], resting['time'], top_id))
            else:
                resting['active'] = False

        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid, is_market=False)
            book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'time': time_counter,
                'active': remaining > 0
            }
            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, time_counter, oid))
                else:
                    heapq.heappush(sell_heap, (price, time_counter, oid))
            time_counter += 1

        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, price, qty, oid, is_market=False)
            book[oid] = {
                'side': side,
                'price': price,
                'qty': 0,
                'time': time_counter,
                'active': False
            }
            time_counter += 1

        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, None, qty, oid, is_market=True)
            book[oid] = {
                'side': side,
                'price': None,
                'qty': 0,
                'time': time_counter,
                'active': False
            }
            time_counter += 1

    return trades

